    """Prompt template for self-critique before retry."""
    return (
        "You are a strict reviewer. Identify factual errors, missing steps, and unsafe actions.
"
        f"Task:
{task}

Answer:
{answer}

"
        "Write a short critique. If the answer is fine, say 'No issues.'"
    )

def self_consistency_vote(answers: list[str]) -> str:
    """Majority vote across self-consistency samples. Time O(n), space O(n)."""
    if not answers:
        return ""
    normalized = [answer.strip().lower() for answer in answers]
    winner, _ = Counter(normalized).most_common(1)[0]
    for answer in answers:
        if answer.strip().lower() == winner:
            return answer
    return answers[0]

def extract_json_block(text: str) -> str:
    """Extract JSON from markdown fences or raw text. Time O(n)."""
    fenced = re.search(r"```(?:json)?\s*(\{[\s\S]*?\}|\[[\s\S]*?\])\s*```", text)
    if fenced:
        return fenced.group(1)
    brace = re.search(r"(\{[\s\S]*\}|\[[\s\S]*\])", text)
    return brace.group(1) if brace else text.strip()

def parse_structured_output[T: BaseModel](text: str, model: type[T]) -> T:
    """Parse and validate LLM output into a Pydantic model. Time O(n)."""
    try:
        payload = json.loads(extract_json_block(text))
    except json.JSONDecodeError:
        payload = json.loads(repair_json(text))
    return model.model_validate(payload)

