def system_prompt_compose(
    role: str,
    constraints: list[str],
    output_format: str | None = None,
) -> str:
    """Compose a structured system prompt from role + constraints."""
    lines = [role.strip(), "", "Constraints:"]
    lines.extend(f"- {item}" for item in constraints)
    if output_format:
        lines.extend(["", "Output format:", output_format.strip()])
    return "\n".join(lines)

def estimate_tokens(messages: list[Message] | str) -> int:
    """Rough token estimate (~4 chars per token). Time O(n)."""
    if isinstance(messages, str):
        text = messages
    else:
        text = "\n".join(message.content for message in messages)
    return max(1, len(text) // 4)

def bias_mitigation_prompt(detected: list[str]) -> str:
    """System addendum to reduce detected bias patterns in agent replies."""
    if not detected:
        return ""
    return (
        "Communication guardrails:\n"
        "- State uncertainty when evidence is incomplete.\n"
        "- Avoid absolute claims unless mathematically or logically provable.\n"
        "- Disagree respectfully when user assumptions conflict with data.\n"
        "- Prefer 'based on available data' over 'definitely'."
    )

def detect_overconfidence_markers(text: str) -> list[str]:
    """Flag absolute language that erodes calibrated trust. Time O(n)."""
    hits: list[str] = []
    for pattern in _OVERCONFIDENCE_PATTERNS:
        if re.search(pattern, text, flags=re.IGNORECASE):
            hits.append(pattern)
    return hits

def detect_sycophancy_markers(text: str) -> list[str]:
    """Flag agreeable filler that reduces honest pushback. Time O(n)."""
    hits: list[str] = []
    for pattern in _SYCOPHANCY_PATTERNS:
        if re.search(pattern, text, flags=re.IGNORECASE):
            hits.append(pattern)
    return hits

def progressive_disclosure_plan(steps: list[str], *, batch_size: int = 3) -> list[list[str]]:
    """Batch complex instructions to reduce cognitive overload. Time O(n)."""
    if batch_size <= 0:
        return [steps]
    return [steps[index : index + batch_size] for index in range(0, len(steps), batch_size)]

def gain_frame(action: str, benefit: str) -> str:
    """Gain-framed message emphasizing positive outcome."""
    return f"If you {action}, you can {benefit}."

def neutral_frame(action: str, fact: str) -> str:
    """Neutral, low-manipulation framing for regulated domains (fintech, health)."""
    return f"Option: {action}. Relevant fact: {fact}. You can proceed or decline."

def sdt_tone_score(text: str) -> dict[str, float]:
    """Score autonomy, competence, and relatedness language (SDT). Time O(n)."""

    def _score(patterns: list[str]) -> float:
        hits = sum(1 for pattern in patterns if re.search(pattern, text, re.I))
        return min(1.0, hits / max(1, len(patterns)))

    return {
        "autonomy": _score(_AUTONOMY),
        "competence": _score(_COMPETENCE),
        "relatedness": _score(_RELATEDNESS),
    }

def default_option_label(action: str, *, recommended: bool = True) -> str:
    """Label a default option (libertarian paternalism). Time O(1)."""
    if recommended:
        return f"{action} (recommended)"
    return action

def cialdini_principle_score(text: str) -> dict[str, float]:
    """Score presence of Cialdini persuasion principles. Time O(n)."""
    scores: dict[str, float] = {}
    for principle, patterns in _CIALDINI_SIGNALS.items():
        hits = sum(1 for pattern in patterns if re.search(pattern, text, re.I))
        scores[principle] = min(1.0, hits / max(1, len(patterns)))
    return scores

def ethical_persuasion_check(text: str, *, domain: str = "general") -> list[str]:
    """Flag manipulative patterns; stricter for fintech. Time O(n)."""
    issues: list[str] = []
    for pattern in _DARK_PATTERNS:
        if re.search(pattern, text, re.I):
            issues.append(f"dark pattern detected: {pattern}")
    if domain in {"fintech", "accounting", "expense"}:
        scores = cialdini_principle_score(text)
        if scores.get("scarcity", 0) > 0.5:
            issues.append("scarcity framing may be inappropriate for regulated financial UX")
    return issues

def agent_trust_score(response: str) -> float:
    """Composite trust score from transparency checklist. Time O(n)."""
    checks = transparency_checklist(response)
    return sum(1.0 for value in checks.values() if value) / len(checks)

def transparency_checklist(response: str) -> dict[str, bool]:
    """Check whether an agent response includes trust-building elements."""
    return {
        "states_limits": bool(
            re.search(r"\b(i can't|i cannot|not sure|uncertain)\b", response, re.I)
        ),
        "cites_source": bool(
            re.search(r"\b(source|according to|based on|reference)\b", response, re.I)
        ),
        "explains_reasoning": bool(
            re.search(r"\bbecause\b|\btherefore\b|\bso that\b", response, re.I)
        ),
        "offers_next_step": bool(
            re.search(r"\bnext step\b|\byou can\b|\bwould you like\b", response, re.I)
        ),
    }

def rate_limit_backoff_ms(attempt: int, *, base_ms: int = 500, cap_ms: int = 30_000) -> int:
    """Exponential backoff for Shopify REST/GraphQL 429 retries. Time O(1), space O(1)."""
    if attempt < 1:
        attempt = 1
    delay = min(cap_ms, base_ms * (2 ** (attempt - 1)))
    jitter = int(delay * 0.1)
    return delay + (attempt % (jitter + 1))

def merge_cart_lines(lines: list[dict[str, Any]]) -> list[dict[str, Any]]:
    """Merge cart lines by variant_id, summing quantities. Time O(n), space O(n)."""
    merged: dict[str, dict[str, Any]] = {}
    for line in lines:
        variant_id = str(line.get("variant_id", ""))
        if not variant_id:
            continue
        if variant_id not in merged:
            merged[variant_id] = {**line, "quantity": int(line.get("quantity", 0))}
        else:
            merged[variant_id]["quantity"] += int(line.get("quantity", 0))
    return list(merged.values())

def inventory_available(on_hand: int, committed: int, incoming: int = 0) -> int:
    """Compute sellable inventory (on hand minus committed plus incoming). Time O(1), space O(1)."""
    return max(0, on_hand - committed + incoming)

def order_tags_from_risk(score: float, *, high: float = 0.75, medium: float = 0.45) -> list[str]:
    """Map fraud risk score to Shopify order tags. Time O(1), space O(1)."""
    if score >= high:
        return ["risk:high", "review-required"]
    if score >= medium:
        return ["risk:medium"]
    return ["risk:low"]

def shopify_transaction_fee(amount_minor: int, rate_bps: int, flat_minor: int = 0) -> int:
    """Compute payment processing fee in minor currency units. Time O(1), space O(1)."""
    if amount_minor <= 0:
        return 0
    percent_fee = math.ceil(amount_minor * rate_bps / 10_000)
    return percent_fee + flat_minor

def parse_shopify_gid(gid: str) -> tuple[str, int] | None:
    """Parse a Shopify global ID into resource type and numeric id. Time O(1), space O(1)."""
    match = _GID_RE.match(gid.strip())
    if not match:
        return None
    return match.group(1), int(match.group(2))

def verify_webhook_hmac(body: bytes, header_hmac: str, secret: str) -> bool:
    """Verify Shopify webhook HMAC-SHA256 signature. Time O(n), space O(1)."""
    digest = hmac.new(secret.encode(), body, hashlib.sha256).digest()
    expected = base64.b64encode(digest).decode()
    return hmac.compare_digest(expected, header_hmac)
